"""Load files generated by V0.12's real save methods, without rewriting them."""

from dataclasses import asdict
import json
from pathlib import Path
import shutil

import pytest

from simsteer.app.settings import Settings
from simsteer.calib.flow import Step
from simsteer.core.calibration import Calibration
from simsteer.core.learners.livecalib import LiveCalib
from simsteer.core.learners.liveparams import LiveParams, TRUST_COVERAGE_VERSION
from simsteer.state import take_state_warnings
from simsteer.state_import import import_legacy_state
from test_calib_flow import new_flow


FIXTURES = Path(__file__).parent / "fixtures" / "v012_state"
FLOW_FILE = "calibflow_ets2_gamepad.json"


def stage_files(tmp_path, monkeypatch, step, through_import, names):
    source, target = tmp_path / "legacy", tmp_path / "active"
    source.mkdir()
    target.mkdir()
    for name in names:
        shutil.copyfile(FIXTURES / step / name, source / name)
    originals = {p.name: p.read_bytes() for p in source.iterdir()}
    if through_import:
        assert import_legacy_state(source, target)
    else:
        for path in source.iterdir():
            shutil.copyfile(path, target / path.name)
    assert {p.name: p.read_bytes() for p in source.iterdir()} == originals
    monkeypatch.setenv("SIMSTEER_DATA_DIR", str(target))
    return target


@pytest.mark.parametrize("step", ["camera", "check", "done"])
@pytest.mark.parametrize("through_import", [False, True], ids=["direct", "import"])
def test_v012_flow_preserves_completed_stages(step, through_import, tmp_path, monkeypatch):
    names = [p.name for p in (FIXTURES / step).glob("*.json")]
    target = stage_files(tmp_path, monkeypatch, step, through_import, names)
    raw = json.loads((FIXTURES / step / FLOW_FILE).read_text())
    assert raw["version"] == 5
    assert raw["camera"]["discard_no_progress_s"] is None
    lc = LiveCalib(game="ets2")
    lp = LiveParams(game="ets2", device_kind="gamepad", lag_frames=0)
    cal = Calibration.load(game="ets2")
    flow = new_flow(lc, lp, cal,
                    model_identity={"model": "upgrade-fixture", "sha256": "0" * 64})
    assert not take_state_warnings(target)
    restored = json.loads(json.dumps(flow.to_dict()))
    # The empty legacy solve gains the timestamp contract; the completed
    # FOV stage, source and every other saved value remain unchanged.
    assert restored["fov"] == {**raw["fov"], "solver": {
        **raw["fov"]["solver"], "time_base_version": 1, "geometry": None}}
    assert restored["steering"] == raw["steering"]
    assert flow.camera_diagnostics() == raw["camera"]
    assert asdict(cal) == json.loads((FIXTURES / step / "calibration_ets2.json").read_text())
    assert flow.attempts == raw["attempts"]
    if step == "camera":
        assert flow.step is Step.CAMERA
        assert flow.redo_note == raw["redo_note"]
        assert flow.result == raw["result"]
    else:
        assert flow.step is Step.CHECK
        assert flow.redo_note == "Check again: saved evidence is outdated"
        assert flow.result["status"] == "INSUFFICIENT_EVIDENCE"
        assert flow.legacy_result == raw["result"]
        assert flow.direction.ready and flow.output_direction.ready and lp.trusted()
        assert not flow.calibrated and not flow.ai_steering_ready


@pytest.mark.parametrize("step", ["camera", "check", "done"])
@pytest.mark.parametrize("through_import", [False, True], ids=["direct", "import"])
@pytest.mark.parametrize("name", ["livecalib_state_ets2.json", "liveparams_ets2_gamepad.json",
                                  "calibration_ets2.json", "settings.json"])
def test_v012_saved_values_are_preserved(name, step, through_import, tmp_path, monkeypatch):
    target = stage_files(tmp_path, monkeypatch, step, through_import, [name])
    raw = json.loads((FIXTURES / step / name).read_text())
    if name.startswith("livecalib"):
        restored = LiveCalib(game="ets2").state_dict()
        assert raw["bootstrap_samples"] > 0
        assert "reset_generation" in raw and "blocked_counts" in raw
    elif name.startswith("liveparams"):
        lp = LiveParams(game="ets2", device_kind="gamepad")
        restored = {"a": lp.a_linear, "b": lp.b_quad, "c": lp.c_bias,
                    **{key: getattr(lp, key) for key in raw if key not in
                       ("a", "b", "c", "coverage_version")},
                    "coverage_version": TRUST_COVERAGE_VERSION}
    elif name.startswith("calibration"):
        restored = asdict(Calibration.load(game="ets2"))
    else:
        restored = asdict(Settings.load())
    assert restored == raw
    assert not take_state_warnings(target)
